import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>WebP ছবি পোর্টালে জমা দেওয়া যাচ্ছে না? অনেক পোর্টাল, পুরোনো সফটওয়্যার আর ছাপার দোকান এখনো WebP নেয় না৤ তখন WebP থেকে JPG-তে কনভার্ট করতে হয়৤</p>\n<p>এই গাইডে আপনি জানবেন কেন WebP প্রত্যাখ্যান হয়, কনভার্টের সময় কী হয়, আর স্বচ্ছতা কীভাবে সামলাবেন৤</p>\n<p>সোশ্যাল মিডিয়া, কাজের নথি আর ছাপার জন্য আলাদা পরামর্শও এখানে আছে৤</p>\n<h2 id=\"why-webp-gets-rejected\">WebP প্রত্যাখ্যান হয় কেন</h2>\n<p>অনেক পোর্টাল শুধু JPG আর PNG নেয়৤ WebP তাদের তালিকায় নেই৤</p>\n<p>পুরোনো সফটওয়্যার WebP চিনতে পারে না৤ ফটো অ্যাপে ছবি খোলে না৤</p>\n<p>ছাপার দোকানেও WebP নাও চলতে পারে৤ তারা JPG ফাইল চায়৤</p>\n<h2 id=\"what-happens-in-conversion\">কনভার্টের সময় কী হয়</h2>\n<p>WebP থেকে JPG-তে গেলে ছবির তথ্য নতুনভাবে লেখা হয়৤ ছবির বিষয় একই থাকে৤</p>\n<p>JPG ক্ষতিকর ফরম্যাট৤ কিছু তথ্য ফেলে দিয়ে ফাইল লেখা হয়৤</p>\n<p>স্বচ্ছতা হারিয়ে যায়৤ JPG স্বচ্ছতা দিতে পারে না৤</p>\n<h2 id=\"transparency-and-matte\">স্বচ্ছতা আর ম্যাট</h2>\n<p>WebP স্বচ্ছতা দিতে পারে৤ JPG-তে গেলে স্বচ্ছ অংশে রং দিতে হয়৤</p>\n<p>সাদা ম্যাট সবচেয়ে বেশি ব্যবহৃত হয়৤ বেশিরভাগ ব্যাকগ্রাউন্ড সাদা হয়৤</p>\n<p>ছবির ব্যাকগ্রাউন্ডের সঙ্গে মিলিয়ে ম্যাটের রং বেছে নিন৤</p>\n<h2 id=\"quality-settings\">কোয়ালিটি সেটিং</h2>\n<p>JPG-তে কোয়ালিটি 85 থেকে 90 ভালো৤ এতে ছবি পরিষ্কার থাকে৤</p>\n<p>WebP থেকে JPG-তে গেলে মান একটু কমতে পারে৤ কোয়ালিটি 90 রাখলে মান ভালো থাকে৤</p>\n<p>ছাপার জন্য কোয়ালিটি 95 রাখুন৤ ছাপায় মান গুরুত্বপূর্ণ৤</p>\n<p>কোয়ালিটি ৯০ শতাংশে রাখলে JPG ছবি প্রায় মূলের মতো থাকে৤ WebP থেকে JPG-তে গেলে ৯০ শতাংশ একটি নিরাপদ মান৤ ৮০ শতাংশে ফাইল ছোট হয়, তবে সূক্ষ্ম বিবরণ কমে৤</p>\n<p>কোয়ালিটি সেট করার সময় ছবির ধরন দেখুন৤ প্রতিকৃতিতে ৯০ শতাংশ ভালো, আর ল্যান্ডস্কেপে ৮৫ শতাংশ যথেষ্ট৤ লেখাযুক্ত ছবিতে ৯০ শতাংশ রাখুন৤</p>\n<p>কোয়ালিটি কমালে ফাইলের আকার দ্রুত কমে৤ ৯০ থেকে ৮০-এ নামালে ফাইল প্রায় এক-তৃতীয়াংশ ছোট হয়৤ মানের পার্থক্য সামান্য৤</p>\n<p>কোয়ালিটি সেট করার পর প্রিভিউতে জুম করে দেখুন৤ চোখের দিকে মনোযোগ দিন৤ চোখ পরিষ্কার থাকলে কোয়ালিটি ঠিক আছে৤</p>\n<p>কোয়ালিটি ৯৫ শতাংশের উপরে রাখলে ফাইল বড় হয়, কিন্তু মানের পার্থক্য ধরা পড়ে না৤ ৯০ শতাংশের উপরে যাওয়া সাধারণত অযথা৤</p>\n<p>WebP থেকে JPG-তে কোয়ালিটি সেট করার সময় লক্ষ্য আকার দেখুন৤ ফাইল বড় হলে কোয়ালিটি কমান, আর লক্ষ্য মিলে গেলে আর কমাবেন না৤</p>\n<p>কোয়ালিটি সেটিং পরে বদলানো যায়৤ মূল WebP ফাইল থাকলে আবার কনভার্ট করা যায়৤ তাই প্রথম চেষ্টায় নিখুঁত সেটিং না পেলেও সমস্যা নেই৤</p>\n<p>কোয়ালিটি সেট করার সময় স্ক্রিনের উজ্জ্বলতা ঠিক রাখুন৤ অন্ধকার স্ক্রিনে ছবি ভালো লাগে, কিন্তু উজ্জ্বল স্ক্রিনে দাগ ধরা পড়ে৤ মাঝারি উজ্জ্বলতায় দেখুন৤</p>\n<p>ব্যাচে কনভার্ট করলে সব ছবিতে একই কোয়ালিটি চলে৤ ভিন্ন ছবিতে ভিন্ন কোয়ালিটি দরকার হলে ছবিগুলো আলাদা ব্যাচে ভাগ করুন৤</p>\n<h2 id=\"animated-webp\">অ্যানিমেটেড WebP</h2>\n<p>অ্যানিমেটেড WebP-তে অনেক ফ্রেম থাকে৤ JPG-তে কনভার্ট করলে শুধু প্রথম ফ্রেম থাকে৤</p>\n<p>অ্যানিমেশন দরকার হলে JPG-তে কনভার্ট করবেন না৤ GIF-তে কনভার্ট করুন৤</p>\n<p>স্থির ছবি দরকার হলে প্রথম ফ্রেমটি JPG-তে নিন৤</p>\n<h2 id=\"batch-converting\">ব্যাচে কনভার্ট করা</h2>\n<p>একসঙ্গে অনেক WebP ছবি JPG-তে করতে বাল্ক কনভার্টার খুলুন৤ সব ফাইল একবারে উঠিয়ে একসঙ্গে JPG করুন৤</p>\n<p>ব্যাচের আগে একটি ছবি পরীক্ষা করুন৤ মান ঠিক আছে কি না দেখুন৤</p>\n<p>WebP থেকে JPG ব্যাচের ফল ZIP ফাইলে ডাউনলোড হয়৤ আনজিপ করে প্রতিটি JPG ছবি দেখে নিন, বিশেষ করে রঙের অংশগুলো৤</p>\n<h2 id=\"file-size-after\">কনভার্টের পর ফাইলের আকার</h2>\n<p>WebP থেকে JPG-তে গেলে ফাইল বড় হয়৤ WebP ছোট, JPG বড়৤</p>\n<p>একটি 140KB WebP ফাইল JPG-তে 200KB হতে পারে৤ এটি স্বাভাবিক৤</p>\n<p>ফাইল বড় হলেও মান ভালো থাকে৤ প্রয়োজনে পরে কমপ্রেস করা যায়৤</p>\n<h2 id=\"where-jpg-works\">JPG কোথায় কাজ করে</h2>\n<p>JPG সব জায়গায় কাজ করে৤ পোর্টাল, ইমেইল, ছাপা — সবাই JPG নেয়৤</p>\n<p>পুরোনো সফটওয়্যারেও JPG চলে৤ এটি সর্বজনীন৤</p>\n<p>সন্দেহ থাকলে JPG ব্যবহার করুন৤ এটি নিরাপদ পছন্দ৤</p>\n<p>JPG সেখানে কাজ করে যেখানে WebP চলে না৤ পুরোনো সফটওয়্যারে JPG খোলে৤ WebP পাঠালে প্রাপক ছবি দেখতে পান না৤</p>\n<p>JPG সেখানে কাজ করে যেখানে পোর্টাল JPG চায়৤ বেশিরভাগ পোর্টালের নিয়মে JPG লেখা থাকে৤ WebP পাঠালে ফরম ফিরে আসে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি ছাপাতে হবে৤ ছাপার দোকানে JPG চলে৤ WebP ছাপার দোকানে নাও চলতে পারে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি ইমেইলে পাঠাতে হবে৤ ইমেইল সেবা JPG সংযুক্তি নেয়৤ WebP সংযুক্তি নাও নিতে পারে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি সোশ্যাল মিডিয়ায় পোস্ট করতে হবে৤ সোশ্যাল মিডিয়া JPG নেয়৤ WebP পোস্ট করলে ছবি নাও দেখাতে পারে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি পুরোনো ডিভাইসে দেখাতে হবে৤ পুরোনো ফোনে WebP খোলে না৤ JPG সব ফোনে খোলে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি আর্কাইভ করতে হবে৤ JPG ফরম্যাট অনেক দিন ধরে আছে৤ ভবিষ্যতেও JPG খোলা যাবে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবি সম্পাদনা করতে হবে৤ বেশিরভাগ এডিটর JPG নেয়৤ WebP সব এডিটরে নাও চলতে পারে৤</p>\n<p>JPG সেখানে কাজ করে যেখানে ছবির মান নিয়ে চিন্তা নেই৤ সাধারণ ছবিতে JPG-এর মান যথেষ্ট৤ WebP-এর সুবিধা সাধারণ ব্যবহারে ধরা পড়ে না৤</p>\n<h2 id=\"checking-quality\">মান যাচাই করা</h2>\n<p>কনভার্টের পর ছবিটি দেখে নিন৤ মূল WebP-এর সঙ্গে তুলনা করুন৤</p>\n<p>রং আর বিবরণে পার্থক্য আছে কি না দেখুন৤ পার্থক্য বড় হলে কোয়ালিটি বাড়ান৤</p>\n<p>ছবি ভালো লাগলে তবেই ব্যবহার করুন৤</p>\n<h2 id=\"webp-to-jpg-vs-png\">WebP থেকে JPG বনাম PNG</h2>\n<p>ছবির জন্য JPG ভালো৤ ফাইল ছোট থাকে৤</p>\n<p>লোগো বা লেখার জন্য PNG ভালো৤ প্রান্ত তীক্ষ্ণ থাকে৤</p>\n<p>স্বচ্ছতা রাখতে চাইলে PNG ব্যবহার করুন৤ JPG-তে স্বচ্ছতা থাকে না৤</p>\n<h2 id=\"metadata-stripped\">মেটাডেটা সরানো</h2>\n<p>কনভার্টের সময় ছবি থেকে GPS ট্যাগ মুছে যায়৤ এতে গোপনীয়তা রক্ষা হয়৤</p>\n<p>ক্যামেরার তথ্যও হারিয়ে যেতে পারে৤ মূল ফাইল সংরক্ষণ করুন৤</p>\n<p>শেয়ার করার আগে মেটাডেটা সরানো ভালো৤</p>\n<h2 id=\"common-mistakes\">সাধারণ ভুলগুলো</h2>\n<p>সবচেয়ে বড় ভুল হলো অ্যানিমেটেড WebP JPG-তে কনভার্ট করা৤ অ্যানিমেশন হারিয়ে যায়৤</p>\n<p>আরেকটি ভুল হলো কোয়ালিটি খুব কম রাখা৤ ছবি ঝাপসা হয়ে যায়৤</p>\n<p>স্বচ্ছ ছবি JPG-তে করার আগে ম্যাটের রং দেখুন৤ ভুল রং ছবি খারাপ করে৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো স্বচ্ছতা ভুলে যাওয়া৤ WebP থেকে JPG-তে গেলে স্বচ্ছতা যায়৤ স্বচ্ছ ছবি JPG-তে করলে সাদা বাক্স দেখা যায়৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো মূল ফাইল না রাখা৤ মূল WebP ছাড়া আবার কনভার্ট করা যায় না৤ কনভার্ট করার আগে মূল সংরক্ষণ করুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো কোয়ালিটি খুব কম রাখা৤ ৫০ শতাংশের নিচে ছবিতে দাগ দেখা যায়৤ কোয়ালিটি ৮৫-এর উপরে রাখুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো প্রিভিউ না দেখে ডাউনলোড করা৤ প্রিভিউতে সমস্যা ধরা পড়ে৤ ডাউনলোডের আগে প্রিভিউ দেখুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো অ্যানিমেটেড WebP JPG-তে করা৤ অ্যানিমেটেড WebP-এর অ্যানিমেশন JPG-তে হারিয়ে যায়৤ অ্যানিমেশন দরকার হলে WebP-তেই থাকুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো ফাইলের নাম না বদলানো৤ IMG_1234 নামের ফাইল পরে খুঁজে পাওয়া কঠিন৤ নামে বিষয় লিখুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো ম্যাটের রং না দেখা৤ স্বচ্ছ ছবিতে সাদা ম্যাট ডিফল্ট থাকে৤ গাঢ় ব্যাকগ্রাউন্ডে সাদা ম্যাট খারাপ দেখায়৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো ব্যাচে ভিন্ন ছবি মেশানো৤ স্বচ্ছ আর সাধারণ ছবি এক ব্যাচে রাখলে কিছু ছবি খারাপ হয়৤ ছবি ভাগ করে ব্যাচ করুন৤</p>\n<p>সবচেয়ে সাধারণ ভুল হলো একই ছবি বারবার কনভার্ট করা৤ বারবার কনভার্ট করলে মান কমে৤ মূল থেকে একবার করুন৤</p>\n<h2 id=\"webp-from-social-media\">সোশ্যাল মিডিয়া থেকে WebP</h2>\n<p>সোশ্যাল মিডিয়া থেকে ডাউনলোড করা ছবি WebP-তে থাকে৤ অনেক অ্যাপে তা খোলে না৤</p>\n<p>ব্যবহার করার আগে JPG-তে কনভার্ট করুন৤ সব জায়গায় ব্যবহার করা যায়৤</p>\n<p>ডাউনলোড করা ছবির মান দেখে নিন৤ সোশ্যাল মিডিয়ার ছবি আগে থেকেই কমপ্রেস করা থাকে৤</p>\n<h2 id=\"webp-for-work-documents\">কাজের নথিতে WebP</h2>\n<p>কাজের নথিতে WebP ব্যবহার করবেন না৤ অফিসের কম্পিউটারে WebP নাও খুলতে পারে৤</p>\n<p>নথির জন্য JPG-তে কনভার্ট করুন৤ সবাই JPG খুলতে পারে৤</p>\n<p>নথি পাঠানোর আগে ফাইলটি খুলে দেখুন৤ সঠিক ফরম্যাটে আছে কি না নিশ্চিত করুন৤</p>\n<h2 id=\"webp-for-printing\">ছাপার জন্য WebP</h2>\n<p>ছাপার দোকানে WebP নাও চলতে পারে৤ ছাপার আগে JPG-তে কনভার্ট করুন৤</p>\n<p>ছাপার জন্য কোয়ালিটি 90 বা তার বেশি রাখুন৤ ছাপায় মান গুরুত্বপূর্ণ৤</p>\n<p>WebP থেকে JPG ছাপার আগে ছাপার মাপ জেনে নিন৤ মাপ অনুযায়ী ছবি তৈরি করুন, যাতে কাগজে ছবি কাটা না পড়ে৤</p>\n<p>কাজের নথিতে WebP ছবি ব্যবহার করার আগে JPG-তে বদলে নিন৤ অফিসের সফটওয়্যার WebP নাও খুলতে পারে৤ JPG সব সফটওয়্যারে খোলে৤</p>\n<p>কাজের নথিতে ছবির আকার দেখুন৤ নথির ফাইল বড় হলে শেয়ার করতে সমস্যা হয়৤ ছবি ছোট করে নথি হালকা রাখুন৤</p>\n<p>কাজের নথিতে ছবির মান পরিষ্কার রাখুন৤ ঝাপসা ছবি নথিতে খারাপ দেখায়৤ পরিষ্কার ছবি ব্যবহার করুন৤</p>\n<p>কাজের নথিতে ছবির নামে বিষয় লিখুন৤ নামে বিষয় থাকলে পরে খুঁজে পাওয়া সহজ হয়৤</p>\n<p>কাজের নথিতে ছবি পাঠানোর আগে প্রিভিউ দেখুন৤ প্রিভিউতে ছবি ঠিকমতো দেখা যাচ্ছে কিনা দেখুন৤</p>\n<p>কাজের নথিতে ছবির মূল ফাইল সংরক্ষণ করুন৤ মূল থেকে আবার তৈরি করা যায়৤</p>\n<p>কাজের নথিতে ছবি ব্যবহার করার সময় কপিরাইট দেখুন৤ ছবিটি আপনার হলে সমস্যা নেই৤ অন্যের ছবি ব্যবহার করবেন না৤</p>\n<p>কাজের নথিতে ছবির ফরম্যাটের নিয়ম দেখুন৤ অফিসের নিয়মে JPG লেখা থাকতে পারে৤ নিয়ম মেনে ছবি তৈরি করুন৤</p>\n<p>কাজের নথিতে ছবি পাঠানোর পর জিজ্ঞেস করুন ছবি দেখা গেছে কিনা৤ ছবি না দেখা গেলে আবার পাঠান৤</p>\n<h2 id=\"converting-for-older-relatives\">বয়স্ক আত্মীয়দের জন্য কনভার্ট করা</h2>\n<p>বয়স্ক আত্মীয়দের ফোনে WebP নাও চলতে পারে৤ শেয়ার করার আগে JPG-তে কনভার্ট করুন৤</p>\n<p>JPG সব ফোনে চলে৤ এটি নিরাপদ পছন্দ৤</p>\n<p>শেয়ার করার আগে ছবিটি দেখে নিন৤ মান ঠিক আছে কি না নিশ্চিত করুন৤</p>\n<h2 id=\"keeping-webp-originals\">মূল WebP ফাইল রাখা</h2>\n<p>মূল WebP ফাইল সংরক্ষণ করুন৤ পরে যেকোনো ফরম্যাটে আবার বানানো যায়৤</p>\n<p>কনভার্ট করা JPG ফাইল কাজের ফোল্ডারে রাখুন৤ মূল WebP ফাইল আলাদা রাখুন৤</p>\n<p>নামে ফরম্যাট লিখুন৤ এতে পরে বোঝা যায় কোনটি মূল আর কোনটি কনভার্ট করা৤</p>\n<p>ধাপে ধাপে পদ্ধতির জন্য দেখুন <a href=\"/bn/blog/webp-to-jpg-kivabe-korben\">WebP থেকে JPG করবেন কীভাবে</a> আর সাপোর্ট নিয়ে জানতে পড়ুন <a href=\"/bn/blog/webp-to-jpg-compatibility\">WebP থেকে JPG: সাপোর্ট</a>৤ PNG-তে করতে <a href=\"/bn/webp-to-png\">WebP থেকে PNG টুল</a> ব্যবহার করুন৤</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"WebP থেকে JPG করতে কত সময় লাগে?","answer":"WebP থেকে JPG কনভার্ট সাধারণত মুহূর্তেই হয়৤ পুরো অ্যালবাম একসঙ্গে করলে কয়েক মিনিট সময় নিতে পারে৤"},{"question":"WebP থেকে JPG করলে কি মান কমে?","answer":"খুব সামান্য৤ কোয়ালিটি 90 রাখলে ছবি প্রায় একই দেখায়৤ ফাইল বড় হয়, কারণ JPG WebP-এর মতো দক্ষ নয়৤"},{"question":"পোর্টাল WebP নেয় না কেন?","answer":"অনেক পোর্টাল শুধু JPG আর PNG নেয়৤ WebP তাদের তালিকায় নেই৤ পুরোনো সিস্টেম WebP চিনতে পারে না৤ পোর্টালে জমা দিতে JPG ব্যবহার করুন৤"},{"question":"অ্যানিমেটেড WebP কি JPG করা যায়?","answer":"যায়, তবে শুধু প্রথম ফ্রেম থাকে৤ অ্যানিমেশন হারিয়ে যায়৤ অ্যানিমেশন দরকার হলে GIF-তে কনভার্ট করুন৤ স্থির ছবি দরকার হলে প্রথম ফ্রেমটি JPG-তে নিন৤"},{"question":"স্বচ্ছ WebP কি JPG করা যায়?","answer":"হ্যাঁ, তবে স্বচ্ছতা হারিয়ে যায়৤ স্বচ্ছ অংশে সাদা বা কালো ম্যাট দিতে হয়৤ স্বচ্ছতা রাখতে চাইলে PNG ব্যবহার করুন৤"},{"question":"সোশ্যাল মিডিয়ার WebP ছবি কি ব্যবহার করা যায়?","answer":"সরাসরি ব্যবহার করা যায়, তবে অনেক অ্যাপে খোলে না৤ ব্যবহার করার আগে JPG-তে কনভার্ট করুন৤ সব জায়গায় ব্যবহার করা যায়৤"}];
